    "title": "Meridian Telemetry \u2014 fleet vehicle GPS & sensor ingest platform for logistics operators API",
    "served_at": "/openapi.json",
    "description": "OpenAPI 3.1 spec for the Meridian Telemetry \u2014 fleet vehicle GPS & sensor ingest platform for logistics operators API, inlined below. All endpoints are relative paths on the same host; construct requests with execute().",
    "document": {
      "openapi": "3.1.0",
      "info": {
        "title": "Meridian Telemetry \u2014 fleet vehicle GPS & sensor ingest platform for logistics operators API",
        "version": "1.0.0",
        "description": "Meridian Fleet API: ingests vehicle telemetry batches, exposes trip rollups, and commits processed batches into the warehouse. Used by logistics integrators wiring dashboards and ETL pipelines."
      },
      "servers": [
        {
          "url": "http://localhost:9001"
        }
      ],
      "paths": {
        "/openapi.json": {
          "get": {
            "summary": "OpenAPI spec doc",
            "security": [
              {
                "none": []
              }
            ]
          }
        },
        "/v3/oauth/token": {
          "post": {
            "summary": "OAuth client_credentials",
            "security": [
              {
                "none": []
              }
            ]
          }
        },
        "/v3/batches": {
          "get": {
            "summary": "List telemetry batches (throttled)",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/batches/{id}": {
          "get": {
            "summary": "Get batch detail",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/batches/{id}/commit": {
          "post": {
            "summary": "Commit a batch",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/trips/rollup": {
          "get": {
            "summary": "Trip rollup (region-gated)",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v2/batches/{id}/commit": {
          "post": {
            "summary": "DEPRECATED commit",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        }
      }
    }
  },
  "updated_at": "2026-06-30T04:11:41.870537+00:00"
}

